"""Roll-up functions for metrics-svc (DATA-3307: empty input must not mimic a real value).

An empty batch does not crash the roll-up (DATA-3290), but the empty result must be
DISTINGUISHABLE from a genuine one. Any figure that is undefined for a no-records input --
a mean, a percentile, an error rate, a category share -- is reported as None (JSON null),
never as 0/0.0, because a real batch can legitimately compute to 0.0 and a consumer would
have no way to tell the two apart. Counts are reported as a true 0: a non-empty batch always
has count >= 1, so count 0 is itself an unambiguous "no records" signal.

Non-empty inputs are unchanged.
"""


def summarize(records):
    if not records:
        # count/total are legitimately 0 and count 0 is the unambiguous empty signal;
        # a mean of no records is undefined, so avg is None rather than a fabricated 0.0.
        return {"count": 0, "total": 0, "avg": None}
    total = sum(r["value"] for r in records)
    return {"count": len(records), "total": total, "avg": total / len(records)}


def average(samples):
    if not samples:
        return None                                     # 0.0 would collide with average([0, 0])
    return sum(samples) / len(samples)


def percentile(samples, p):
    if not samples:
        return None                                     # 0.0 would collide with a real 0-valued percentile
    s = sorted(samples)
    k = int(round((p / 100.0) * (len(s) - 1)))
    return s[k]


def error_rate(records):
    if not records:
        return None                                     # 0.0 would read as "healthy", hiding an ingestion gap
    errors = sum(1 for r in records if r.get("error"))
    return errors / len(records)


def top_category(records):
    if not records:
        # category None is the unambiguous empty signal; a share of no records is undefined.
        return {"category": None, "share": None}
    counts = {}
    for r in records:
        counts[r["category"]] = counts.get(r["category"], 0) + 1
    top = max(counts, key=counts.get)
    return {"category": top, "share": counts[top] / len(records)}

